--
-- Name: mv_creator_engagement; Type: MATERIALIZED VIEW; Schema: public; Owner: user6
--

CREATE MATERIALIZED VIEW public.mv_creator_engagement AS
 WITH module_scores AS (
         SELECT c.user_id,
            count(l.id) AS likes,
            (0)::bigint AS comments,
            (0)::bigint AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.xpi_videos c
             LEFT JOIN public.like_video l ON ((l.video_id = c.id)))
          WHERE (c.user_id IS NOT NULL)
          GROUP BY c.user_id
        UNION ALL
         SELECT c.user_id,
            (0)::bigint AS likes,
            count(cm.id) AS comments,
            (0)::bigint AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.xpi_videos c
             LEFT JOIN public.video_comment cm ON ((cm.video_id = c.id)))
          WHERE (c.user_id IS NOT NULL)
          GROUP BY c.user_id
        UNION ALL
         SELECT orig.user_id,
            (0)::bigint AS likes,
            (0)::bigint AS comments,
            count(share.id) AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.xpi_videos share
             JOIN public.xpi_videos orig ON ((share.shared_post_id = orig.id)))
          WHERE ((orig.user_id IS NOT NULL) AND (share.shared_post_id IS NOT NULL))
          GROUP BY orig.user_id
        UNION ALL
         SELECT c.user_id,
            (0)::bigint AS likes,
            (0)::bigint AS comments,
            (0)::bigint AS shares,
            count(v.id) AS views,
            (0)::bigint AS followers
           FROM (public.xpi_videos c
             LEFT JOIN public.viewed_video v ON ((v.video_id = c.id)))
          WHERE (c.user_id IS NOT NULL)
          GROUP BY c.user_id
        UNION ALL
         SELECT c.user_id,
            count(l.id) AS likes,
            (0)::bigint AS comments,
            (0)::bigint AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.pic_tours c
             LEFT JOIN public.like_pic l ON ((l.pic_tours_id = c.id)))
          WHERE (c.user_id IS NOT NULL)
          GROUP BY c.user_id
        UNION ALL
         SELECT c.user_id,
            (0)::bigint AS likes,
            count(cm.id) AS comments,
            (0)::bigint AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.pic_tours c
             LEFT JOIN public.pic_comment cm ON ((cm.pic_tours_id = c.id)))
          WHERE (c.user_id IS NOT NULL)
          GROUP BY c.user_id
        UNION ALL
         SELECT orig.user_id,
            (0)::bigint AS likes,
            (0)::bigint AS comments,
            count(share.id) AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.pic_tours share
             JOIN public.pic_tours orig ON ((share.shared_post_id = orig.id)))
          WHERE ((orig.user_id IS NOT NULL) AND (share.shared_post_id IS NOT NULL))
          GROUP BY orig.user_id
        UNION ALL
         SELECT c.user_id,
            (0)::bigint AS likes,
            (0)::bigint AS comments,
            (0)::bigint AS shares,
            count(v.id) AS views,
            (0)::bigint AS followers
           FROM (public.pic_tours c
             LEFT JOIN public.viewed_pic v ON ((v.pic_tours_id = c.id)))
          WHERE (c.user_id IS NOT NULL)
          GROUP BY c.user_id
        UNION ALL
         SELECT c.user_id,
            count(l.id) AS likes,
            (0)::bigint AS comments,
            (0)::bigint AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.qafi c
             LEFT JOIN public.like_qafi l ON ((l.qafi_id = c.id)))
          WHERE (c.user_id IS NOT NULL)
          GROUP BY c.user_id
        UNION ALL
         SELECT c.user_id,
            (0)::bigint AS likes,
            count(cm.id) AS comments,
            (0)::bigint AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.qafi c
             LEFT JOIN public.qafi_comment cm ON ((cm.qafi_id = c.id)))
          WHERE (c.user_id IS NOT NULL)
          GROUP BY c.user_id
        UNION ALL
         SELECT orig.user_id,
            (0)::bigint AS likes,
            (0)::bigint AS comments,
            count(share.id) AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.qafi share
             JOIN public.qafi orig ON ((share.shared_post_id = orig.id)))
          WHERE ((orig.user_id IS NOT NULL) AND (share.shared_post_id IS NOT NULL))
          GROUP BY orig.user_id
        UNION ALL
         SELECT c.user_id,
            count(l.id) AS likes,
            (0)::bigint AS comments,
            (0)::bigint AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.gebc c
             LEFT JOIN public.like_gebc l ON ((l.gebc_id = c.id)))
          WHERE (c.user_id IS NOT NULL)
          GROUP BY c.user_id
        UNION ALL
         SELECT c.user_id,
            (0)::bigint AS likes,
            count(cm.id) AS comments,
            (0)::bigint AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.gebc c
             LEFT JOIN public.gebc_comment cm ON ((cm.gebc_id = c.id)))
          WHERE (c.user_id IS NOT NULL)
          GROUP BY c.user_id
        UNION ALL
         SELECT orig.user_id,
            (0)::bigint AS likes,
            (0)::bigint AS comments,
            count(share.id) AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.gebc share
             JOIN public.gebc orig ON ((share.shared_post_id = orig.id)))
          WHERE ((orig.user_id IS NOT NULL) AND (share.shared_post_id IS NOT NULL))
          GROUP BY orig.user_id
        UNION ALL
         SELECT c.user_id,
            count(l.id) AS likes,
            (0)::bigint AS comments,
            (0)::bigint AS shares,
            (0)::bigint AS views,
            (0)::bigint AS followers
           FROM (public.news c
             LEFT JOIN public.like_news l ON ((l.news_id = c.id)))
          WHERE (c.user_id IS NOT NULL)
          GROUP BY c.user_id
        UNION ALL
         SELECT c.user_id,
            (0)::bigint AS likes,
            count(cm.id) AS comments,
            (0)::bigint AS shares,
            (0)::bigint AS views,
